def stable_unique(items):
    seen = []
    result = []
    for item in items:
        if not _contains(seen, item):
            seen.append(item)
            result.append(item)
    return result


def _contains(seq, target):
    for x in seq:
        if _deep_equal(x, target):
            return True
    return False


def _deep_equal(a, b):
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        if len(a) != len(b):
            return False
        for k in a:
            if k not in b:
                return False
            if not _deep_equal(a[k], b[k]):
                return False
        return True
    if isinstance(a, (list, tuple)):
        if len(a) != len(b):
            return False
        for x, y in zip(a, b):
            if not _deep_equal(x, y):
                return False
        return True
    try:
        return a == b
    except Exception:
        return False
