def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    first_seen = {}
    counts = {}

    for i, word in enumerate(words):
        key = word.lower()
        if key not in first_seen:
            first_seen[key] = i
            counts[key] = 0
        counts[key] += 1

    # Build list of (key, count, first_index)
    items = [(key, counts[key], first_seen[key]) for key in counts]

    # Sort: count descending, then first_index ascending
    items.sort(key=lambda x: (-x[1], x[2]))

    # Map back to original spelling using first occurrence
    result = []
    for key, count, _ in items[:k]:
        # Find original spelling from first occurrence
        original = None
        for w in words:
            if w.lower() == key:
                original = w
                break
        result.append((original, count))

    return result
