import json
import math


def parse_jsonl_metrics(lines: list[str]) -> dict:
    invalid = 0
    services = {}

    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        try:
            record = json.loads(stripped)
        except (json.JSONDecodeError, ValueError):
            invalid += 1
            continue

        if not isinstance(record, dict):
            invalid += 1
            continue

        service = record.get("service")
        latency_ms = record.get("latency_ms")
        status = record.get("status")

        if not isinstance(service, str):
            invalid += 1
            continue
        if not isinstance(latency_ms, (int, float)) or isinstance(latency_ms, bool):
            invalid += 1
            continue
        if not isinstance(status, (int, float)) or isinstance(status, bool):
            invalid += 1
            continue

        if service not in services:
            services[service] = {"count": 0, "ok": 0, "latencies": []}
        services[service]["count"] += 1
        if 200 <= status < 300:
            services[service]["ok"] += 1
        services[service]["latencies"].append(latency_ms)

    result = {"invalid": invalid}
    for name in sorted(services.keys()):
        data = services[name]
        n = data["count"]
        ok_rate = data["ok"] / n if n > 0 else 0.0
        if n == 0:
            p95 = None
        else:
            sorted_lat = sorted(data["latencies"])
            idx = math.ceil(0.95 * n) - 1
            p95 = sorted_lat[idx]
        result[name] = {"count": n, "ok_rate": ok_rate, "p95_latency_ms": p95}

    return result
