class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__(f"Cycle detected: {' -> '.join(cycle)}")
        self.cycle = cycle


def dependency_plan(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    node_set = set(nodes)
    for a, b in edges:
        if a not in node_set or b not in node_set:
            raise ValueError(f"Unknown node in edge: ({a}, {b})")

    adj = {n: set() for n in nodes}
    in_degree = {n: 0 for n in nodes}

    seen_edges = set()
    for a, b in edges:
        if a == b:
            cycle = [a, a]
            raise CycleError(cycle)
        if (a, b) in seen_edges:
            continue
        seen_edges.add((a, b))
        if b not in adj[a]:
            adj[a].add(b)
            in_degree[b] += 1

    import heapq
    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(nodes):
        # Find actual cycle
        cycle = _find_cycle(adj, nodes)
        raise CycleError(cycle)

    return result


def _find_cycle(adj, nodes):
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in nodes}
    parent = {}

    def dfs(u):
        color[u] = GRAY
        for v in adj[u]:
            if color[v] == GRAY:
                # Found cycle, reconstruct
                cycle = [v, u]
                cur = u
                while parent.get(cur) is not None and parent[cur] != v:
                    cur = parent[cur]
                    cycle.append(cur)
                cycle.append(v)
                cycle.reverse()
                return cycle
            if color[v] == WHITE:
                parent[v] = u
                res = dfs(v)
                if res:
                    return res
        color[u] = BLACK
        return None

    for n in nodes:
        if color[n] == WHITE:
            res = dfs(n)
            if res:
                return res
    return []
