import time


def retry_call(fn, attempts, retry_if, *, base_delay=0.01, sleep=time.sleep):
    if attempts <= 0:
        raise ValueError("attempts must be > 0")

    last_exception = None
    for n in range(1, attempts + 1):
        try:
            return fn()
        except Exception as e:
            last_exception = e
            if n < attempts and retry_if(e):
                delay = base_delay * 2 ** (n - 1)
                sleep(delay)
            else:
                raise
    raise last_exception
