from copy import deepcopy


def apply_patch_ops(document: dict, operations) -> dict:
    new_doc = deepcopy(document)
    staged = []

    try:
        for op, path, value in operations:
            if op not in ('set', 'delete', 'increment'):
                raise ValueError(f"Unknown operation: {op}")

            if not isinstance(path, str) or path == '':
                raise ValueError(f"Invalid path: {path!r}")

            parts = path.split('.')
            _validate_path_parts(parts)

            if op == 'set':
                _set_path(new_doc, parts, value)
            elif op == 'delete':
                _delete_path(new_doc, parts)
            elif op == 'increment':
                _increment_path(new_doc, parts, value)

            staged.append((op, path, value))

    except Exception:
        raise

    return new_doc


def _validate_path_parts(parts):
    for p in parts:
        if not isinstance(p, str) or p == '':
            raise ValueError(f"Invalid path segment: {p!r}")


def _set_path(doc, parts, value):
    if len(parts) == 1:
        doc[parts[0]] = value
        return

    current = doc
    for i, key in enumerate(parts[:-1]):
        if key not in current or not isinstance(current[key], dict):
            current[key] = {}
        current = current[key]

        if not isinstance(current, dict):
            raise TypeError(
                f"Path segment {parts[:i+1]} is not a dict"
            )

    current[parts[-1]] = value


def _delete_path(doc, parts):
    if len(parts) == 1:
        if parts[0] in doc:
            del doc[parts[0]]
        return

    current = doc
    for i, key in enumerate(parts[:-1]):
        if key not in current:
            return
        current = current[key]
        if not isinstance(current, dict):
            return

    last = parts[-1]
    if last in current:
        del current[last]


def _increment_path(doc, parts, value):
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        raise TypeError(
            f"increment value must be int or float, got {type(value).__name__}"
        )

    if len(parts) == 1:
        if parts[0] not in doc:
            raise KeyError(f"Path not found: {'.'.join(parts)}")
        current_val = doc[parts[0]]
    else:
        current = doc
        for i, key in enumerate(parts[:-1]):
            if key not in current or not isinstance(current[key], dict):
                raise KeyError(f"Path not found: {'.'.join(parts)}")
            current = current[key]
        last = parts[-1]
        if last not in current:
            raise KeyError(f"Path not found: {'.'.join(parts)}")
        current_val = current[last]

    if isinstance(current_val, bool) or not isinstance(current_val, (int, float)):
        raise TypeError(
            f"Value at path '{'.'.join(parts)}' must be int or float, "
            f"got {type(current_val).__name__}"
        )

    new_val = current_val + value
    if len(parts) == 1:
        doc[parts[0]] = new_val
    else:
        current = doc
        for key in parts[:-1]:
            current = current[key]
        current[parts[-1]] = new_val
