import threading
import time
from collections import OrderedDict
from typing import Any, Callable, Optional


class TTLCache:
    def __init__(self, maxsize: int, ttl: float, *, clock: Callable[[], float] = time.time):
        if maxsize <= 0:
            raise ValueError("maxsize must be positive")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self._maxsize = maxsize
        self._ttl = ttl
        self._clock = clock
        self._data: "OrderedDict[Any, tuple[Any, float]]" = OrderedDict()
        self._lock = threading.RLock()

    def get(self, key: Any, default: Any = None) -> Any:
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return default
            value, expire_at = entry
            if self._clock() >= expire_at:
                del self._data[key]
                return default
            self._data.move_to_end(key)
            return value

    def set(self, key: Any, value: Any) -> None:
        with self._lock:
            expire_at = self._clock() + self._ttl
            if key in self._data:
                self._data[key] = (value, expire_at)
                self._data.move_to_end(key)
            else:
                self._data[key] = (value, expire_at)
                while len(self._data) > self._maxsize:
                    self._evict_lru_unexpired()

    def delete(self, key: Any) -> None:
        with self._lock:
            self._data.pop(key, None)

    def __len__(self) -> int:
        with self._lock:
            self._purge_expired()
            return len(self._data)

    def _purge_expired(self) -> None:
        now = self._clock()
        expired_keys = [k for k, (_, exp) in self._data.items() if now >= exp]
        for k in expired_keys:
            del self._data[k]

    def _evict_lru_unexpired(self) -> None:
        now = self._clock()
        while len(self._data) > self._maxsize:
            for k, (_, exp) in self._data.items():
                if now < exp:
                    del self._data[k]
                    break
            else:
                break
