import threading
from typing import Callable, Any, Optional, Dict


class IdempotentEventProcessor:
    def __init__(self, apply: Callable[[Any], Any]):
        self._apply = apply
        self._lock = threading.Lock()
        # event_id -> {'state': 'pending'|'done', 'result': Any, 'exc': Exception, 'thread': Thread, 'cond': Condition, 'refcount': int}
        self._events: Dict[Any, dict] = {}

    def process(self, event_id, payload):
        with self._lock:
            entry = self._events.get(event_id)
            if entry is None:
                entry = {
                    'state': 'pending',
                    'result': None,
                    'exc': None,
                    'cond': threading.Condition(self._lock),
                    'refcount': 1,
                    'owner': True,
                }
                self._events[event_id] = entry
                owner = True
            else:
                owner = False
                entry['refcount'] += 1

        if owner:
            # Release lock during apply to avoid blocking other event_ids
            try:
                result = self._apply(payload)
            except BaseException as exc:
                with self._lock:
                    entry['state'] = 'done'
                    entry['exc'] = exc
                    cond = entry['cond']
                    cond.notify_all()
            else:
                with self._lock:
                    entry['state'] = 'done'
                    entry['result'] = result
                    cond = entry['cond']
                    cond.notify_all()
        else:
            # Wait for the owner to finish
            cond = entry['cond']
            with cond:
                while entry['state'] == 'pending':
                    cond.wait()
                if entry['exc'] is not None:
                    raise entry['exc']
                return entry['result']

    def result(self, event_id):
        with self._lock:
            entry = self._events.get(event_id)
            if entry is None or entry['state'] != 'done' or entry['exc'] is not None:
                raise KeyError(event_id)
            return entry['result']
