import threading
from copy import deepcopy


class VersionedStore:
    def __init__(self):
        self._lock = threading.RLock()
        self._data = {}      # key -> value
        self._versions = {}  # key -> version (int)

    def read(self, key):
        with self._lock:
            if key not in self._data:
                return None, 0
            return deepcopy(self._data[key]), self._versions[key]

    def compare_and_set(self, key, expected_version, value):
        with self._lock:
            current_version = self._versions.get(key, 0)
            if current_version != expected_version:
                return False
            self._data[key] = deepcopy(value)
            self._versions[key] = current_version + 1
            return True

    def delete(self, key, expected_version):
        with self._lock:
            current_version = self._versions.get(key, 0)
            if current_version != expected_version:
                return False
            if key in self._data:
                del self._data[key]
            self._versions[key] = current_version + 1
            return True

    def snapshot(self):
        with self._lock:
            return {
                key: (deepcopy(value), self._versions[key])
                for key, value in self._data.items()
            }
