#!/bin/sh
# 处理 TAB 分隔访问日志: timestamp \t status \t latency_ms \t path
# p99 取法: 对每个 path 的 latency_ms 升序排序后, 取第 ceil(0.99 * N) 个元素 (1-indexed)
#          即 awk 中 NR == int(0.99 * total) + 1; 若 N < 100 则取最大值
# 资源开销: 流式处理, 内存仅与 (唯一 path 数 × 每 path 延迟数组) 成正比,
#          不读取整文件到 shell 变量; 排序在 awk 数组内完成, 适合 path 数有限场景

awk -F'\t' '
function quantile(sorted, n,    q) {
    q = int(0.99 * n) + 1
    if (q > n) q = n
    if (q < 1) q = 1
    return sorted[q]
}
function insert(arr, n, v,    i, j) {
    for (i = n; i > 0 && arr[i] > v; i--) arr[i+1] = arr[i]
    arr[i+1] = v
}
{
    path = $4
    cnt[path]++
    if ($2 ~ /^5/) err[path]++
    insert(lat[path], cnt[path] - (cnt[path] - (cnt[path] > 0 ? 1 : 0)) + 0, $3)
    # 上面 insert 调用简化为: insert(lat[path], nlat[path]++, $3)
    nlat[path]++
}
END {
    for (p in cnt) {
        printf "%s\t%d\t%d\t%d\n", p, cnt[p], err[p]+0, quantile(lat[p], nlat[p])
    }
}' "$1" | sort -t$'\t' -k3,3nr -k1,1
